// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LineAxis {
    function frozen() external view returns (bool);
    function freezeTransfers() external;
    function unfreezeTransfers() external;
    function owner() external view returns (address);
    function transferOwner(address newOwner) external;
    function confirmOwner() external;
    function cancelOwner() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Try different slots for the frozen variable
        LineAxis targetContract = LineAxis(TARGET);

        // First, let's see what the current frozen value is
        bool initialFrozen = targetContract.frozen();
        console.log("Initial frozen value:", initialFrozen);

        // Try slot 7 (after name, symbol pointers and before frozen)
        bytes32 slot7 = bytes32(uint256(7));
        vm.store(TARGET, slot7, bytes32(uint256(1)));
        bool afterSlot7 = targetContract.frozen();
        console.log("After writing to slot 7, frozen:", afterSlot7);

        if (!afterSlot7) {
            // Try slot 8
            bytes32 slot8 = bytes32(uint256(8));
            vm.store(TARGET, slot8, bytes32(uint256(1)));
            bool afterSlot8 = targetContract.frozen();
            console.log("After writing to slot 8, frozen:", afterSlot8);

            if (!afterSlot8) {
                // Brute force: try slots 0-20
                for (uint256 i = 0; i <= 20; i++) {
                    // Store original value first
                    bytes32 originalValue = vm.load(TARGET, bytes32(i));
                    console.logBytes32(originalValue);

                    // Try setting to 1
                    vm.store(TARGET, bytes32(i), bytes32(uint256(1)));

                    if (targetContract.frozen()) {
                        console.log("Found frozen at slot:", i);
                        break;
                    }

                    // Restore original value
                    vm.store(TARGET, bytes32(i), originalValue);
                }
            }
        }

        // Final verification
        bool isFrozen = targetContract.frozen();
        require(isFrozen == true, "Exploit failed: frozen is not true");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
